def compare_happiness(a, b):
    """
    Create a function that takes two strings representing real numbers. 
    The function should first check if each string is 'happy' or not. 
    A string is 'happy' if its length is at least 3 and every 3 consecutive characters are distinct.
    If neither string is 'happy', return None. 
    If only one string is 'happy', return that string.
    If both strings are 'happy', compare them as real numbers (the floating point might be . or ,) 
    and return the larger number as a string. If they are equal, return None.

    Note: If a real number is represented as a string, the floating point might be . or ,

    compare_happiness("1,234", "5,678") is "5,678"
    compare_happiness("1,112", "3,344") is None
    compare_happiness("1,123", "1,123") is None
    compare_happiness("1,234", "1,112") is "1,234"
    """

    def is_happy(s):
        s = s.replace(',', '.')
        if len(s) < 3:
            return False
        for i in range(len(s) - 2):
            if s[i] == s[i - 1] or s[i] == s[i + 2] or s[i + 1] == s[i + 2]:
                return False
        return True
    a_happy = is_happy(a)
    b_happy = is_happy(b)
    if not a_happy and (not b_happy):
        return None
    elif a_happy and (not b_happy):
        return a
    elif not a_happy and b_happy:
        return b
    else:
        a_float = a.replace(',', '.')
        b_float = b.replace(',', '.')
        if float(a_float) > float(b_float):
            return a
        elif float(a_float) < float(b_float):
            return b
        else:
            return None

